function playSfx(kind='tap'){
 if(!soundEnabled)return;
 const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;
 try{audioContext??=new Audio();if(audioContext.state==='suspended')audioContext.resume();const now=audioContext.currentTime;
  const tones=kind==='attack'?[160,95]:kind==='summon'?[440,660,880]:kind==='effect'?[740,980]:kind==='phase'?[330,520]:[420];
  tones.forEach((hz,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type=kind==='attack'?'sawtooth':'triangle';osc.frequency.setValueAtTime(hz,now+i*.055);gain.gain.setValueAtTime(.0001,now+i*.055);gain.gain.exponentialRampToValueAtTime(kind==='attack'?.075:.035,now+i*.055+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+i*.055+.13);osc.connect(gain).connect(audioContext.destination);osc.start(now+i*.055);osc.stop(now+i*.055+.14)});
 }catch{}
}
function go(p){if(p!==page){pageTrail.push(page);history.pushState({ringControl:true,page:p},'',`#${p}`)}page=p;render()}
function goBack(){if(pageTrail.length){history.back();return}if(page!=='home'){page='home';history.replaceState({ringControl:true,page},'','#home');render()}}
if(!history.state?.ringControl)history.replaceState({ringControl:true,page},'','#home');
window.addEventListener('popstate',e=>{if(e.state?.ringControl){page=e.state.page;if(pageTrail.length)pageTrail.pop()}else{page='home';pageTrail.length=0}render()});
function button(label,attrs='',cls='button'){return `<button class="${cls}" ${attrs}>${label}</button>`}
function cardTile(c,add=false,n=0){const full=(decks.find(x=>x.id===deckId)?.cards.length||0)>=DECK_MAX;const label=n>=COPIES_MAX?'Maximum 2':full?'Deck complet':'＋ Ajouter';return `<article class="card-tile" data-view-card="${c.id}" tabindex="0"><img loading="lazy" src="/${c.image}" alt="${esc(c.displayName)}"><div class="card-meta"><b>${esc(c.displayName)}</b><span>${esc(c.category)}${c.rarity?' · '+c.rarity:''}${c.attack!=null?` · ${c.attack} ATT / ${c.endurance} END`:''}</span>${add?button(`${label} · ${n}/2`,`data-add="${c.id}" ${n>=COPIES_MAX||full?'disabled':''}`):''}</div></article>`}function header(title){$("#pageTitle").textContent=title;$("#deckCount").textContent=decks.length;$("#collectionCount").textContent=catalog.length;$("#backButton").hidden=page==="home"}
function home(){header('La cloche va sonner.');return `<div class="hero"><div class="hero-content"><span class="hero-kicker">WWE TCG · MODE SOLO</span><h2>Entre dans<br>l’arène.</h2><p>Compose ton deck, choisis tes actions carte par carte et affronte une IA locale. Les cartes et leurs visuels d’origine restent intacts.</p><div class="hero-actions">${button('Lancer un duel →','data-go="duel"','button button-primary')}${button('Construire mon deck','data-go="decks"')}</div></div></div><div class="stats"><div class="stat"><b>${catalog.filter(c=>c.playable).length}</b><span>CARTES DISPONIBLES</span></div><div class="stat"><b>${decks.length}</b><span>DECKS PERSONNELS</span></div><div class="stat"><b>${match?'À reprendre':'500'}</b><span>${match?'DUEL SAUVEGARDÉ':'PV AU DÉPART'}</span></div></div><div class="section-head"><div><h2>Ton univers</h2><p>Les règles fondamentales sont appliquées par le jeu. Les effets de cartes se déclenchent depuis leur texte imprimé.</p></div></div><div class="notice">Mode actuel : 1 joueur contre une IA locale. Deck composé manuellement : 40 à 50 cartes, 2 exemplaires maximum par carte. Les fiches restent marquées à vérifier là où l’extraction des PDF est incertaine.</div>`}
