function lobby(){
 header('Choisis ton deck');const valid=decks.filter(d=>validateDeck(d).valid);
 const signatureOptions=SIGNATURE_DECKS.map(d=>`<option value="signature:${d.id}" ${preferredDeck===`signature:${d.id}`?'selected':''}>${esc(d.name)} · ${d.cards.length} cartes</option>`).join('');
 const customOptions=valid.map(d=>`<option value="custom:${d.id}" ${preferredDeck===`custom:${d.id}`?'selected':''}>${esc(d.name)} · ${d.cards.length} cartes</option>`).join('');
 return `<div class="duel-lobby"><div class="lobby-copy"><span class="hero-kicker">1 JOUEUR · CONTRE IA</span><h2>Prépare<br>le combat.</h2><p>Choisis un deck signature, un de tes decks, ou retourne à l’éditeur pour en créer un.</p></div><div class="panel lobby-panel"><h3>Ton deck</h3>${match?'<div class="notice">Une partie est sauvegardée. Tu peux la reprendre ou démarrer un nouveau duel avec le deck choisi.</div>':''}<select class="select" id="chosenDeck"><optgroup label="Decks signature">${signatureOptions}</optgroup>${customOptions?`<optgroup label="Mes decks">${customOptions}</optgroup>`:''}</select><small class="lobby-rules">40 cartes · maximum 2 exemplaires · règles originales</small><p>${button('Entrer dans l’arène →','data-start="1"','button button-primary')} ${match?button('Reprendre la partie','data-resume="1"','icon-btn'):''} ${button('Créer ou modifier un deck','data-go="decks"')}</p></div></div>`
}function readableEffect(source){
 const tokens=[...source.matchAll(/[\p{L}\p{N}]+|[^\s\p{L}\p{N}]/gu)];let start=-1,end=-1,lastGoodEnd=-1,long=0,short=0,best={text:'',long:0};
 const finish=()=>{if(long>=4&&lastGoodEnd>start){let text=source.slice(start,lastGoodEnd).replace(/\s+/g,' ').replace(/^[\s:–-]+|[\s:–-]+$/g,'').replace(/^[\p{Ll}](?=\p{Lu})/u,'');if(long>best.long||long===best.long&&text.length>best.text.length)best={text,long}}start=-1;end=-1;lastGoodEnd=-1;long=0;short=0};
 for(const token of tokens){const value=token[0],index=token.index,isWord=/[\p{L}\p{N}]/u.test(value);if(isWord){if(value.length>=3){if(start<0)start=index;end=index+value.length;lastGoodEnd=end;long++;short=0}else if(start>=0&&short<2){end=index+value.length;short++}else finish()}else if(start>=0){end=index+value.length;if(/[.!?;]/.test(value))lastGoodEnd=end}}
 finish();return best
}
