function zone(p,kind,label,pi){const list=p[kind],count=kind==='active'?3:2;return `<div class="board-zone ${kind}-zone"><div class="zone-title"><span>${label}</span><small>${list.length}/${count}</small></div><div class="zone-cards">${Array.from({length:count},(_,i)=>{const f=list[i],c=f&&card(f.cardId);return f?`<button class="field-card ${gameState.turn===pi&&gameState.usedAttackers.includes(f.instanceId)?'is-spent':''}" data-card-preview="${f.cardId}" data-fighter="${pi}:${f.instanceId}" aria-label="${esc(c?.displayName)}, ${f.attack} attaque, ${f.endurance} endurance"><img src="/${c?.image}" alt=""><span class="field-caption"><b>${esc(c?.displayName)}</b><small><strong>${f.attack} ATT</strong><i>·</i><strong>${f.endurance} END</strong></small></span></button>`:`<div class="empty-slot"><span>＋</span><small>EMPLACEMENT</small></div>`}).join('')}</div></div>`}
