function duel(){header('Duel · Tour '+(gameState.turnNumber));if(!gameState)return lobby();const pending=gameState.pendingAttack,win=gameState.winner!==null;const phase=gameState.phase==='reaction'?'RÉACTION':gameState.phase==='attacks'?'ATTAQUE':'ACTIONS';const preview=hoveredPreviewId||pinnedPreviewId;return `<div class="duel-screen"><div class="match-top"><div class="match-state"><span class="hero-kicker">${gameState.phase==='reaction'?'⚡ FENÊTRE DE RÉPONSE':'TOUR '+gameState.turnNumber+' · '+(gameState.turn===0?'À TOI':'IA')}</span><h2>${win?`${esc(gameState.players[gameState.winner].name)} gagne`:(gameState.phase==='reaction'?'CHOISIS TA RÉPONSE':gameState.phase==='attacks'?'À L’ATTAQUE':'TON TERRAIN')}</h2><p>${pending?`${esc(gameState.players[pending.playerIndex].name)} annonce une attaque. Les Momenta rapides sont disponibles maintenant.`:'Survole une carte pour la lire. Clique pour voir ses actions et choisir.'}</p></div><div class="match-round"><span>DUEL <b>SOLO</b></span><span>TOUR <b>${gameState.turnNumber}</b></span></div><button class="sound-toggle ${soundEnabled?'sound-on':''}" data-sound-toggle aria-pressed="${soundEnabled}" title="Activer ou couper les bruitages">${soundEnabled?'🔊 SON':'🔇 MUET'}</button>${button('Quitter','data-quit="1"','button button-quiet')}</div><div class="duel-layout"><section class="duel-center"><div class="arena"><div class="arena-lights"></div><div class="arena-scoreboard"><span>THE ARENA</span><b>${String(gameState.turnNumber).padStart(2,'0')}</b></div>${fighterBlock(1)}<div class="ring-divider"><span class="rope"></span><b>VS</b><span class="rope"></span></div>${fighterBlock(0)}</div>${playerHand()}<div class="duel-controls">${quickResponseMarkup()}<div class="control-hint"><b>${phase}</b><span>${gameState.turn===0?'Les effets légaux apparaissent ici et dans le panneau de carte.':'L’IA enchaîne automatiquement ses actions et ses attaques.'}</span></div>${pending?button('Résoudre l’attaque','data-resolve="1"','button button-primary'):''}${!win&&gameState.turn===0&&gameState.phase==='actions'?button('Passer aux attaques →','data-attacks="1"','button button-primary'):''}${!win&&gameState.turn===0&&gameState.phase==='attacks'?button('Terminer mon tour','data-end="1"','button button-primary'):''}</div><details class="match-log"><summary>Journal du match <span>${gameState.history.length} actions</span></summary><div>${gameState.history.slice(0,10).map(x=>`<p>${esc(x)}</p>`).join('')}</div></details></section><aside id="cardInspector" class="card-inspector" aria-live="polite">${inspectorMarkup(preview)}</aside></div></div>`}
