function modal(html){const m=$('#modal');m.innerHTML=html;if(!m.open)m.showModal()}
function actionOption(title,detail,attrs=''){return `<button class="action-option" ${attrs}><b>${title}</b><small>${detail}</small></button>`}
function cardActions(id){const c=card(id),p=gameState.players[0],inHand=p.hand.includes(id),acting=gameState.turn===0&&gameState.phase==='actions';if(!c)return;let options='';const effects=cardEffects(c);
if(c.category==='Catcheur'&&inHand&&acting){const requirement=normalSummonRequirement(c);if(requirement.allowed&&!p.limits.normal){const board=p.active.concat(p.passive).map(f=>card(f.cardId));const canSac=c.rarity!=='SSR'||board.some(x=>x?.rarity==='SR')||board.filter(x=>x?.rarity==='R').length>=2;options+=actionOption('Invocation normale',canSac?`${c.rarity==='SSR'?'Sacrifice 1 SR ou 2 R':'Sans sacrifice'} · choisir la position`:'Impossible : il faut un SR ou deux R sur le terrain',`data-normal="${id}" ${canSac?'':'disabled'}`)}}
if(c.category==='Manager'&&inHand&&acting&&!p.limits.manager&&!p.manager)options+=actionOption('Jouer le manager','Occupe ton emplacement Manager ce tour','data-manager="'+id+'"');
if(c.category==='Objet'&&inHand&&acting&&!p.limits.object&&(p.active.length+p.passive.length>0))options+=actionOption('Équiper un objet','Choisir le catcheur porteur','data-object="'+id+'"');
if(c.category==='Momentum'&&inHand&&((acting&&!c.rapid&&p.limits.momentum<1)||(gameState.pendingAttack&&gameState.pendingAttack.playerIndex===1&&c.rapid&&gameState.outOfTurnMomentumUsed[0]<1)))options+=actionOption(c.rapid?'Jouer le Momentum rapide ⚡':'Jouer le Momentum',c.rapid?'Réponse après l’annonce de l’attaque adverse':'Une fois pendant ta phase d’action',`data-momentum="${id}"`);
modal(`<div class="action-modal"><div class="action-card"><img src="/${c.image}" alt=""><div><span class="hero-kicker">${esc(c.category)}${c.rapid?' · ⚡ MOMENTUM RAPIDE':''}</span><h3>${esc(c.displayName)}</h3><p>${c.attack!=null?`${c.attack} ATT · ${c.endurance} END · `:''}Lis le texte sur le visuel imprimé, conservé sans modification.</p></div></div>${effects.length?`<div class="modal-printed-effects"><h4>EFFETS REPÉRÉS</h4>${effects.map(x=>`<p><b>${x.kind.toUpperCase()}</b> · ${esc(x.text)}</p>`).join("")}${c.needsReview?"<small>Texte OCR à vérifier sur la carte.</small>":""}</div>`:""}<div class="action-options">${options||'<p class="notice">Aucune action légale avec cette carte dans la situation actuelle.</p>'}${actionOption('Voir la carte en grand','Conserver le visuel imprimé','data-zoom="'+id+'"')}</div><button class="button action-back" data-close>Fermer</button></div>`)}
function fighterOptions(f,pi){
 const p=gameState.players[pi],c=card(f.cardId),my=pi===0&&gameState.turn===0&&gameState.phase==='actions';let out='';
 if(pi===0&&gameState.turn===0&&gameState.phase==='attacks'&&f.position==='active'&&!gameState.usedAttackers.includes(f.instanceId)){
  const d=gameState.players[1],direct=Math.max(0,p.active.length-d.active.length)>gameState.directAttacksUsed,targets=d.active.filter(x=>!gameState.usedTargets.includes(x.instanceId));
  if(direct||targets.length)out+=actionOption('Attaquer',`${f.attack} ATT · choisir une cible`,`data-attack="${f.instanceId}"`)
 }
 if(my){
  if(!p.limits.move){if(f.position==='active'&&p.active.length>1&&p.passive.length<2)out+=actionOption('Déplacer vers passif','Une fois par tour',`data-move="${f.instanceId}:passive"`);if(f.position==='passive'&&p.active.length<3)out+=actionOption('Déplacer vers actif','Une fois par tour',`data-move="${f.instanceId}:active"`)}
  const printed=cardEffects(c),hasPassive=printed.some(e=>e.kind==='passif'),hasSpecial=printed.some(e=>e.kind==='spécial');
  if(hasPassive)out+=actionOption('Activer l’effet passif',f.passiveUsedTurn===gameState.turnNumber?'Déjà activé ce tour':'Appliquer le texte imprimé',`data-effect="${pi}:${f.instanceId}:passive" ${f.passiveUsedTurn===gameState.turnNumber?'disabled':''}`);
  if(f.position==='active'&&hasSpecial&&c.id!=='wyatt-11'){out+=actionOption('Activer l’effet spécial',f.specialUsed?'Déjà utilisé pendant cette présence':'Appliquer le texte imprimé',`data-effect="${pi}:${f.instanceId}:special" ${f.specialUsed?'disabled':''}`);if(!f.specialUsed&&/invoqu|revien|ramen|ressuscit/i.test(c.textSnippet||''))out+=actionOption('Invocation spéciale','Choisir la zone et le catcheur autorisés par l’effet',`data-special="${pi}:${f.instanceId}"`)}
 }
 for(const[stat,label]of[['attack','ATT'],['endurance','END']])for(const delta of[-5,5])out+=actionOption(`${label} ${delta>0?'+':''}${delta}`,'Correction manuelle, ajoutée au journal',`data-adjust="${pi}:${f.instanceId}:${stat}:${delta}"`);
 return out
}function positionPick(id,special=false){const p=gameState.players[0];let opts='';if(p.active.length<3&&p.active.length+p.passive.length<5)opts+=actionOption('Placer en actif','Peut attaquer',`data-position="${id}:active:${special}"`);if(p.active.length>0&&p.passive.length<2&&p.active.length+p.passive.length<5)opts+=actionOption('Placer en passif','Ne peut pas attaquer',`data-position="${id}:passive:${special}"`);modal(`<div class="action-modal"><h3>Choisir la position</h3><div class="action-options">${opts||'<p>Aucune place légale.</p>'}</div></div>`)}
function respondAI(){if(!match||!match.pendingAttack||match.pendingAttack.playerIndex!==0)return;const p=match.players[1],c=p.hand.map(card).find(x=>x?.category==="Momentum"&&x.rapid);if(c){game.playMomentum(match,1,c);if(c.id!=="momentum-20")game.resolveMomentum(match,1);persist();render()}}


function animateAttack(attack){
 if(!attack)return Promise.resolve();
 return new Promise(resolve=>{
  const start=document.querySelector('[data-fighter="'+attack.playerIndex+':'+attack.attackerId+'"]');
  const target=attack.targetId==='direct'?document.querySelector('[data-hp="'+(1-attack.playerIndex)+'"]'):document.querySelector('[data-fighter="'+(1-attack.playerIndex)+':'+attack.targetId+'"]');
  if(!start||!target){setTimeout(resolve,420);return}
  const a=start.getBoundingClientRect(),z=target.getBoundingClientRect(),x=a.left+a.width/2,y=a.top+a.height/2,tx=z.left+z.width/2,ty=z.top+z.height/2,dx=tx-x,dy=ty-y,dist=Math.hypot(dx,dy);
  const beam=document.createElement('div');beam.className='attack-beam';beam.style.left=x+'px';beam.style.top=y+'px';beam.style.setProperty('--attack-distance',dist+'px');beam.style.setProperty('--attack-angle',Math.atan2(dy,dx)+'rad');
  const impact=document.createElement('div');impact.className='attack-impact';impact.style.left=tx+'px';impact.style.top=ty+'px';impact.textContent='−'+attack.attack+(attack.targetId==='direct'?' PV':' END');
  document.body.append(beam,impact);target.classList.add('attack-target-flash');try{playSfx('attack')}catch{}
  setTimeout(()=>{beam.remove();impact.remove();target.classList.remove('attack-target-flash');resolve()},760)
 })
}

async function runAI(){
 if(!match||match.turn!==1||match.winner!==null||busy)return;
 busy=true;
 const s=match,p=s.players[1],lookup=id=>card(id),pause=()=>new Promise(resolve=>setTimeout(resolve,550));
 try{
  await pause();
  if(s.phase==='actions'){
   for(const id of [...p.hand]){
    const c=lookup(id);
    if(c?.category==='Catcheur'&&!p.limits.normal){
     let sacrifices=[];
     if(c.rarity==='SSR'){
      const board=[...p.active,...p.passive].map(f=>({f,c:lookup(f.cardId)}));
      const sr=board.find(x=>x.c?.rarity==='SR'),rs=board.filter(x=>x.c?.rarity==='R');
      if(sr)sacrifices=[sr.f.instanceId];else if(rs.length>=2)sacrifices=rs.slice(0,2).map(x=>x.f.instanceId);else continue;
     }
     const position=p.active.length<3?'active':p.passive.length<2&&p.active.length?'passive':null;
     if(position)game.normalSummon(s,1,c,sacrifices,position);
    }else if(c?.category==='Manager'&&!p.limits.manager&&!p.manager)game.playManager(s,1,c);
    else if(c?.category==='Objet'&&!p.limits.object){const fighter=p.active[0]||p.passive[0];if(fighter)game.equipObject(s,1,c,fighter.instanceId)}
    else if(c?.category==='Momentum'&&!c.rapid&&!p.limits.momentum){const result=game.playMomentum(s,1,c);if(result.ok)game.resolveMomentum(s,1)}
   }
  }
  if(s.turn!==1||s.winner!==null)return;
  s.phase='attacks';persist();render();await pause();
  for(const fighter of [...p.active]){
   if(s.turn!==1||s.winner!==null)break;
   const targets=s.players[0].active,directLimit=Math.max(0,p.active.length-targets.length);
   const target=targets.find(t=>!s.usedTargets.includes(t.instanceId));
   if(target)game.declareAttack(s,1,fighter.instanceId,target.instanceId);
   else if(s.directAttacksUsed<directLimit)game.declareAttack(s,1,fighter.instanceId,'direct');
   else continue;
   persist();render();
   const hasRapid=s.players[0].hand.some(id=>{const c=lookup(id);return c?.category==='Momentum'&&c.rapid&&s.outOfTurnMomentumUsed[0]<1});
   if(hasRapid||hasSamiAttackResponse(s))return;
   await animateAttack(s.pendingAttack);if(s.pendingAttack)game.resolveAttack(s);persist();render();await pause();
  }
  if(s.turn===1&&s.winner===null&&!s.pendingAttack){
   const result=game.endTurn(s);
   if(!result.ok&&s.winner===null)message(result.reason||'L’IA ne peut pas terminer son tour.');
   persist();render();
  }
 }catch(error){
  console.error('Erreur pendant le tour automatique de l’IA',error);
  message('Le tour automatique de l’IA a rencontré un problème. Consulte le journal du match.');
 }finally{busy=false;persist()}
}

function beginAI(){game.endTurn(match);persist();render();runAI()}
function message(s){const m=$('#toast');if(!m)return;m.textContent=s;m.classList.add('show');setTimeout(()=>m.classList.remove('show'),2400)}
function newMatch(deck){forceLobby=false;const ai=catalog.filter(c=>c.playable);let aiDeck=[];for(let i=0;aiDeck.length<40&&i<ai.length;i++)aiDeck.push(ai[i].id);for(let i=0;aiDeck.length<40&&i<ai.length;i++)aiDeck.push(ai[i].id);const selected=deck.cards.slice();match=game.createMatch(selected,aiDeck);match.players[0].name='Vous';match.players[1].name='L’IA';persist();go('duel')}
$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)go(b.dataset.view)});$('#quickNewDeck').onclick=()=>{go('decks');setTimeout(()=>$('[data-new]')?.click(),0)};
document.addEventListener('pointerover',e=>{const el=e.target.closest('[data-card-preview]');if(!el)return;hoveredPreviewId=el.dataset.cardPreview;const pane=$('#cardInspector');if(pane)pane.innerHTML=inspectorMarkup(hoveredPreviewId)});
