$('#view').addEventListener('click',e=>{const tile=e.target.closest('[data-view-card]');if(!tile||e.target.closest('[data-add]'))return;const c=card(tile.dataset.viewCard);if(c)modal(`<div class="action-modal"><div class="action-card"><img src="/${c.image}" alt=""><div><span class="hero-kicker">${esc(c.category)} · PAGE ${c.page}</span><h3>${esc(c.displayName)}</h3><p>${c.attack!=null?`${c.attack} ATT · ${c.endurance} END · `:''}Visuel original conservé depuis ${esc(c.source)}.</p></div></div><img class="card-zoom" src="/${c.image}" alt="${esc(c.displayName)}"></div>`)});$('#view').addEventListener('input',e=>{if(e.target.id==='deckName'){const d=decks.find(x=>x.id===deckId);if(d){d.name=e.target.value;persist()}}if(e.target.id==='search'||e.target.id==='deckSearch')filterCards()});$('#view').addEventListener('change',e=>{if(e.target.id==='filter'||e.target.id==='deckFilter')filterCards()});function filterCards(){const search=($('#search')?.value||$('#deckSearch')?.value||'').toLowerCase(),typ=$('#filter')?.value||$('#deckFilter')?.value||'',items=$$('#collection .card-tile,#deckCards .card-tile');items.forEach((el,i)=>{const c=catalog.find(x=>el.querySelector('img')?.getAttribute('src')===`/${x.image}`);el.hidden=Boolean(c&&((typ&&c.category!==typ)||(search&&!`${c.displayName} ${c.textSnippet}`.toLowerCase().includes(search))))})}
$('#view').addEventListener('click',e=>{const b=e.target.closest('[data-go]');if(b)go(b.dataset.go)});
